import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { DownloadRow } from '../types'
import {
  advance,
  barText,
  DETAIL_ROWS,
  describe,
  downloadSizes,
  extractUrls,
  fileLabel,
  formatBytes,
  formatDuration,
  isLauncherWrapper,
  isWslCommand,
  layout,
  MAX_ROWS,
  noneFinished,
  outputName,
  padLabel,
  parseReport,
  parseWslTick,
  restartsAfter,
  wslCommand,
  wslReport,
} from './lib'
import type { Description, Finished, Report, RowState, WslLaunch, WslTick } from './lib'

const rowsAtom = atom({ plugin: 'download-bar', key: 'rows' } as const, [])
const summaryAtom = atom({ plugin: 'download-bar', key: 'summary' } as const, null)
const isHidden = atom({ plugin: 'download-bar', key: 'isHidden' } as const, false)

// Flip on to trace the sampler's reports and each row's life to DEBUG_LOG, in the mod's own folder.
const DEBUG = false
const DEBUG_LOG = 'download-bar-debug.log'
const RECENT_CALLS = 20
// A script naming more URLs than this is a crawler or a list, not one download.
const MAX_SCRIPT_URLS = 20
const MAX_SCRIPT_BYTES = 512 * 1024

// A WSL sampler stops once its distro has had no wsl.exe from the shells and no rows this long...
const WSL_IDLE_MS = 15_000
// ...and one that ends on its own is not started again for this long.
const WSL_RETRY_MS = 10_000

type ShellCall = { tool: 'Bash' | 'PowerShell'; command: string; at: number }

// One distro's sampler (sampler/wsl-sampler.sh) and the rows it follows.
type WslSource = {
  /** The distro as `keyOf` names it: lower case, '' for the default until its name is known. */
  key: string
  slot: number
  /** Its name, from the sampler's first line. */
  distro: string
  rows: Map<number, RowState>
  /** Linux processes WSL started for a shell's wsl.exe; kept after that wsl.exe exits. */
  ours: Set<number>
  idleSince: number | null
  isStopping: boolean
}

// Module state: a hot reload starts it over along with a fresh sampler.
const S = {
  rows: new Map<number, RowState>(),
  wsl: new Map<string, WslSource>(),
  // The commands the shells' running wsl.exe processes run.
  launches: [] as { distro: string; command: string }[],
  slots: new Map<string, number>(),
  wslRetryAt: new Map<string, number>(),
  defaultDistro: '',
  rx: 0,
  sims: [] as DownloadRow[],
  calls: [] as ShellCall[],
  // The current batch: from the first row shown until the panel empties.
  finished: noneFinished as Finished,
  isSummaryMode: false,
  pinned: [] as number[],
  published: '',
  buffer: '',
  restarts: 0,
  isSimulating: false,
  log: [] as string[],
}

async function dbg($: EngineInterface, line: string) {
  if (!DEBUG) return
  S.log.push(`${new Date(await $.clock.now()).toISOString().slice(11, 23)} ${line}`)
  if (S.log.length > 120) S.log.shift()
  await $.fs.write(`${$.plugin.root}/${DEBUG_LOG}`, `${S.log.join('\n')}\n`).catch(() => undefined)
}

async function settings($: EngineInterface) {
  const [on, lookup] = await Promise.all([$.store.get('on'), $.store.get('lookup')])
  return { isOn: on !== false, isLookup: lookup !== false }
}

// A shell process that is itself the downloader (PowerShell's WebClient, say)
// has Claude Code's launcher as its command line: name it from the latest
// command Claude gave that tool before the process connected.
function labelFor(exe: string, cmd: string, firstSeen: number): Description {
  if (!isLauncherWrapper(cmd)) return describe(exe, cmd)

  const tool = /^(pwsh|powershell)/i.test(exe) ? 'PowerShell' : 'Bash'
  const call = [...S.calls].reverse().find(c => c.tool === tool && c.at <= firstSeen + 1000)
  if (call === undefined) return { label: tool, urls: [] }

  const urls = extractUrls(call.command)
  const output = outputName(call.command)
  if (output !== null) return { label: output, urls }
  if (urls.length > 0) return { label: fileLabel(urls[0] as string), urls }
  return { label: tool, urls }
}

type Head = { size: number; type: string } | null

// HEAD with curl, redirects followed: the final hop's size and type.
async function lookUpHead($: EngineInterface, url: string): Promise<Head> {
  try {
    const run = await $.process.run(['curl.exe', '-sIL', '--max-time', '8', url], { timeoutMs: 12000 })
    const lengths = [...run.stdout.matchAll(/^content-length:\s*(\d+)/gim)].map(m => Number(m[1]))
    const types = [...run.stdout.matchAll(/^content-type:\s*([^\r\n;]+)/gim)].map(m => m[1] as string)
    const size = lengths[lengths.length - 1]
    return size !== undefined && size > 0 ? { size, type: types[types.length - 1] ?? '' } : null
  } catch {
    return null
  }
}

async function setTotal($: EngineInterface, pid: number, total: number) {
  for (const rows of [S.rows, ...[...S.wsl.values()].map(source => source.rows)]) {
    const row = rows.get(pid)
    if (row === undefined) continue
    rows.set(pid, { ...row, total })
    await publish($)
    return
  }
}

// URLs on the command line are the download: every one must answer a size.
// Runs only once a process is already downloading, so never for a command
// you denied.
async function lookUpCommandUrls($: EngineInterface, pid: number, urls: string[]) {
  const heads = await Promise.all(urls.map(url => lookUpHead($, url)))
  await dbg($, `size pid=${pid} ${JSON.stringify(heads)}`)
  if (heads.some(h => h === null)) return
  await setTotal($, pid, heads.reduce((sum, h) => sum + (h as { size: number }).size, 0))
}

// A script's URLs are read from its source; only those answering like files
// (big enough, not a page or an API reply) count toward its size.
async function lookUpScriptUrls($: EngineInterface, pid: number, script: string) {
  let source: string
  try {
    const stat = await $.fs.stat(script)
    if (stat.kind !== 'file' || stat.size > MAX_SCRIPT_BYTES) return
    source = await $.fs.read(script)
  } catch {
    await dbg($, `script unreadable pid=${pid} ${script}`)
    return
  }
  const urls = extractUrls(source, MAX_SCRIPT_URLS + 1).filter(u => !/^https?:\/\/(localhost|127\.|\[::1\])/i.test(u))
  await dbg($, `script pid=${pid} ${script} urls=${urls.length}`)
  if (urls.length === 0 || urls.length > MAX_SCRIPT_URLS) return

  const total = downloadSizes(await Promise.all(urls.map(url => lookUpHead($, url))))
  await dbg($, `script size pid=${pid} ${total}`)
  if (total !== null) await setTotal($, pid, total)
}

// A resumed download's file already held what an earlier run wrote: count
// that too, so its percent starts where the file is, not at zero.
async function countResumed($: EngineInterface, pid: number, file: string) {
  let size: number
  try {
    const stat = await $.fs.stat(file)
    if (stat.kind !== 'file') return
    size = stat.size
  } catch {
    await dbg($, `resume file unreadable pid=${pid} ${file}`)
    return
  }
  for (const rows of [S.rows, ...[...S.wsl.values()].map(source => source.rows)]) {
    const row = rows.get(pid)
    if (row === undefined) continue
    const earlier = size - (row.writes - row.base)
    await dbg($, `resume pid=${pid} file=${size} earlier=${earlier}`)
    if (earlier <= 0) return
    rows.set(pid, { ...row, base: row.base - earlier })
    await publish($)
    return
  }
}

function toRow(r: RowState): DownloadRow {
  return {
    id: r.pid,
    label: r.label,
    bytes: r.writes - r.base,
    total: r.total,
    rate: r.rate,
    status: r.status,
    exitCode: r.exitCode,
  }
}

async function publish($: EngineInterface) {
  const real = [...S.rows.values(), ...[...S.wsl.values()].flatMap(source => [...source.rows.values()])]
    .filter(r => r.isVisible)
    .sort((a, b) => a.firstSeen - b.firstSeen)
    .map(toRow)
  const all = [...real, ...S.sims]

  // A batch ends when the panel empties; its tallies and mode go with it.
  if (all.length === 0) {
    S.finished = noneFinished
    S.isSummaryMode = false
    S.pinned = []
  }

  const shown = layout(all, S.pinned, S.finished, S.isSummaryMode)
  S.pinned = shown.pinned
  S.isSummaryMode = shown.summary !== null

  const text = JSON.stringify(shown)
  if (text === S.published) return
  S.published = text
  await update($, rowsAtom, () => shown.rows)
  await update($, summaryAtom, () => shown.summary)
}

// Shown rows that left the panel still count in the batch's summary.
function retire(rows: Iterable<RowState>) {
  for (const old of rows) {
    if (!old.isVisible) continue
    S.finished = {
      done: S.finished.done + (old.status === 'failed' ? 0 : 1),
      failed: S.finished.failed + (old.status === 'failed' ? 1 : 0),
      bytes: S.finished.bytes + (old.writes - old.base),
      total: S.finished.total + (old.total ?? 0),
      hasUnknownTotal: S.finished.hasUnknownTotal || old.total === null,
    }
  }
}

// Moves one source's rows on by its report: the Windows sampler's, or a distro's.
async function step($: EngineInterface, before: Map<number, RowState>, report: Report, isLookup: boolean): Promise<Map<number, RowState>> {
  const now = await $.clock.now()
  const { rows, appeared } = advance(before, report, now, labelFor)

  for (const row of rows.values()) {
    const old = before.get(row.pid)
    if (old === undefined) await dbg($, `seen pid=${row.pid} ${row.exe} label=${row.label} script=${row.script} cmd=${row.cmd.slice(-100)}`)
    else if (old.status !== row.status) await dbg($, `${row.status} pid=${row.pid} bytes=${row.writes - row.base} exit=${row.exitCode} visible=${row.isVisible}`)
  }

  retire([...before].filter(([pid]) => !rows.has(pid)).map(([, old]) => old))

  if (appeared.length > 0) await update($, isHidden, () => false)
  for (const row of appeared) {
    await dbg($, `show pid=${row.pid} label=${row.label} urls=${row.urls.length}`)
    if (row.resumeFile !== null) void countResumed($, row.pid, row.resumeFile)
    if (!isLookup) continue
    if (row.urls.length > 0) void lookUpCommandUrls($, row.pid, row.urls)
    else if (row.script !== null) void lookUpScriptUrls($, row.pid, row.script)
  }
  return rows
}

async function onReport($: EngineInterface, line: string) {
  const report = parseReport(line)
  if (report === null) {
    await dbg($, `sampler: ${line.slice(0, 200)}`)
    return
  }
  S.rx = report.rx
  const { isOn, isLookup } = await settings($)
  if (!isOn) {
    S.rows.clear()
    for (const source of S.wsl.values()) source.rows.clear()
    await followWsl($, [])
    await publish($)
    return
  }

  S.rows = await step($, S.rows, report, isLookup)
  await followWsl($, report.wsl ?? [])
  await publish($)
}

function keyOf(distro: string): string {
  return (distro === '' ? S.defaultDistro : distro).toLowerCase()
}

// Starts a sampler in each distro a shell's wsl.exe runs in, and stops one
// whose distro has gone quiet.
async function followWsl($: EngineInterface, launches: WslLaunch[]) {
  const now = await $.clock.now()
  S.launches = launches.filter(l => l.x === undefined).flatMap(l => wslCommand(l.cmd) ?? [])
  for (const { distro } of S.launches) {
    const key = keyOf(distro)
    if (!S.wsl.has(key) && now >= (S.wslRetryAt.get(key) ?? 0)) startWslSampler($, key, distro)
  }
  for (const source of S.wsl.values()) {
    if (source.rows.size > 0 || S.launches.some(l => keyOf(l.distro) === source.key)) source.idleSince = null
    else if (source.idleSince === null) source.idleSince = now
    else if (now - source.idleSince >= WSL_IDLE_MS) source.isStopping = true
  }
}

// The sampler's first line names the distro: a default one is filed under its name from then on.
function learnDistro(source: WslSource, distro: string) {
  source.distro = distro
  if (source.key !== '' || distro === '') return
  S.defaultDistro = distro
  S.wsl.delete('')
  source.key = distro.toLowerCase()
  if (S.wsl.has(source.key)) source.isStopping = true
  else S.wsl.set(source.key, source)
}

async function onWslTick($: EngineInterface, source: WslSource, tick: WslTick) {
  const { isOn, isLookup } = await settings($)
  if (!isOn || source.isStopping) return
  for (const root of source.ours) if (!tick.roots.has(root)) source.ours.delete(root)
  const report = wslReport(tick, source.slot, source.distro || source.key, S.rx, (root, cmd) => {
    if (source.ours.has(root)) return true
    if (!S.launches.some(l => keyOf(l.distro) === source.key && isWslCommand(cmd, l.command))) return false
    source.ours.add(root)
    return true
  })
  source.rows = await step($, source.rows, report, isLookup)
  await publish($)
}

function startWslSampler($: EngineInterface, key: string, distro: string) {
  const slot = S.slots.get(key) ?? S.slots.size
  S.slots.set(key, slot)
  const source: WslSource = { key, slot, distro, rows: new Map(), ours: new Set(), idleSince: null, isStopping: false }
  S.wsl.set(key, source)
  void (async () => {
    let buffer = ''
    let block: string[] = []
    try {
      const child = $.process.spawn({
        argv: [
          'wsl.exe',
          ...(distro === '' ? [] : ['-d', distro]),
          '--cd',
          `${$.plugin.root}/sampler`.replace(/\//g, '\\'),
          '-e',
          'bash',
          'wsl-sampler.sh',
        ],
      })
      await dbg($, `wsl sampler start ${distro || '(default)'}`)
      // Leaving the loop ends the sampler.
      for await (const chunk of child) {
        if (source.isStopping) break
        if (chunk.stream === 'stderr') {
          await dbg($, `wsl sampler stderr: ${chunk.text.slice(0, 300)}`)
          continue
        }
        buffer += chunk.text
        const lines = buffer.split(/\r?\n/)
        buffer = lines.pop() ?? ''
        for (const line of lines) {
          if (line.startsWith('D\t')) learnDistro(source, line.slice(2))
          else if (line === 'T') block = []
          else if (line === 'E') await onWslTick($, source, parseWslTick(block))
          else block.push(line)
        }
      }
    } catch (error) {
      await dbg($, `wsl sampler failed: ${String(error)}`)
    }
    await dbg($, `wsl sampler end ${source.distro || '(default)'} stopping=${source.isStopping}`)
    if (S.wsl.get(source.key) === source) S.wsl.delete(source.key)
    if (!source.isStopping) S.wslRetryAt.set(source.key, (await $.clock.now()) + WSL_RETRY_MS)
    retire(source.rows.values())
    await publish($)
  })()
}

function startSampler($: EngineInterface) {
  void (async () => {
    // Half a line left by the sampler that ended would be glued onto the new one's first report.
    S.buffer = ''
    const began = await $.clock.now()
    try {
      const child = $.process.spawn({
        argv: [
          'powershell',
          '-NoProfile',
          '-NonInteractive',
          '-ExecutionPolicy',
          'Bypass',
          '-WindowStyle',
          'Hidden',
          '-File',
          `${$.plugin.root}/sampler/sampler.ps1`,
        ],
      })
      for await (const chunk of child) {
        if (chunk.stream === 'stderr') {
          await dbg($, `sampler stderr: ${chunk.text.slice(0, 300)}`)
          continue
        }
        S.buffer += chunk.text
        const lines = S.buffer.split(/\r?\n/)
        S.buffer = lines.pop() ?? ''
        for (const line of lines) if (line.trim() !== '') await onReport($, line)
      }
    } catch (error) {
      await dbg($, `sampler failed: ${String(error)}`)
    }
    const restarts = restartsAfter(S.restarts, (await $.clock.now()) - began)
    if (restarts !== null) {
      S.restarts = restarts
      $.clock.after(5000, () => startSampler($))
    }
  })()
}

// Pretend downloads, to see the bar without touching the network: two by
// default (one of a known size, one not), or `count` of them to see the
// summary that takes over past MAX_ROWS.
function simulate($: EngineInterface, startedAt: number, count: number) {
  const MB = 1024 * 1024
  const plans =
    count <= 2
      ? [
          { id: -1, label: 'sample-model.safetensors', total: 240 * MB, rate: 18 * MB, isSized: true },
          { id: -2, label: 'fetch_dataset.py', total: 60 * MB, rate: 7 * MB, isSized: false },
        ]
      : Array.from({ length: count }, (_, i) => ({
          id: -(i + 1),
          label: `shard-${String(i + 1).padStart(2, '0')}.parquet`,
          total: (20 + ((i * 37) % 90)) * MB,
          rate: (3 + ((i * 13) % 17)) * MB,
          isSized: true,
        }))
  S.isSimulating = true
  const timer = $.clock.every(250, async () => {
    const elapsed = ((await $.clock.now()) - startedAt) / 1000
    const before = S.sims
    S.sims = plans.flatMap(p => {
      const finishesAt = p.total / p.rate
      if (elapsed >= finishesAt + 1.5) return []
      const isDone = elapsed >= finishesAt
      const wobble = 0.85 + 0.15 * Math.sin(elapsed * 2 + p.id)
      return [
        {
          id: p.id,
          label: p.label,
          bytes: isDone ? p.total : p.rate * elapsed,
          total: p.isSized ? p.total : null,
          rate: isDone ? 0 : p.rate * wobble,
          status: isDone ? ('done' as const) : ('active' as const),
          exitCode: isDone ? 0 : null,
        },
      ]
    })
    for (const old of before) {
      if (S.sims.some(r => r.id === old.id)) continue
      S.finished = { ...S.finished, done: S.finished.done + 1, bytes: S.finished.bytes + old.bytes, total: S.finished.total + (old.total ?? 0), hasUnknownTotal: S.finished.hasUnknownTotal || old.total === null }
    }
    if (S.sims.length === 0) {
      timer.cancel()
      S.isSimulating = false
    }
    await publish($)
  })
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // The rows are the host's and outlive a reload; the processes behind them
    // are this module's to follow, so every load starts with none.
    await update($, rowsAtom, () => [])
    await update($, summaryAtom, () => null)
    await $.command.register({
      name: 'dlbar',
      description: 'Download progress bar: on|off, test [count], lookup on|off',
      argumentHint: 'on|off|test [count]|lookup on|off',
      immediate: true,
    })
    startSampler($)
    return next(e)
  })

  // Remembered only to name a download made by the shell process itself.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    S.calls = [...S.calls, { tool: 'Bash' as const, command: e.command, at: await $.clock.now() }].slice(-RECENT_CALLS)
    return next(e)
  })

  on('tool.call', { tool: 'PowerShell' }, async ($, e, next) => {
    S.calls = [...S.calls, { tool: 'PowerShell' as const, command: e.command, at: await $.clock.now() }].slice(-RECENT_CALLS)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const [rows, summary] = await Promise.all([read($, rowsAtom), read($, summaryAtom)])
    if (rows.length === 0 || e.props.hasSurvey || (await read($, isHidden))) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    const summaryLabel = summary === null ? '' : `${summary.count} downloads`
    const nameWidth = Math.max(8, Math.min(28, Math.max(summaryLabel.length, ...rows.map(r => r.label.length))))
    const barWidth = Math.max(10, Math.min(24, e.props.bodyColumns - nameWidth - 52))
    const hideButton = <Button key="hide" label="Hide" onPress={() => update($, isHidden, () => true)} />

    let top = null
    if (summary !== null) {
      const isSized = summary.total !== null && summary.total > 0 && summary.bytes <= summary.total * 1.05
      const fraction = isSized ? Math.min(summary.active > 0 ? 0.99 : 1, summary.bytes / (summary.total as number)) : 0
      const sizes = isSized ? `${formatBytes(summary.bytes)} / ${formatBytes(summary.total as number)}` : formatBytes(summary.bytes)
      const counts = [
        summary.active > 0 ? `${formatBytes(summary.rate)}/s` : null,
        summary.done > 0 ? `${summary.done} done` : null,
        summary.failed > 0 ? `${summary.failed} failed` : null,
      ].filter(part => part !== null)
      top = (
        <Box key="summary">
          <Text color={summary.active > 0 ? 'cyan' : summary.failed > 0 ? 'red' : 'green'}>{summary.active > 0 ? '↓' : summary.failed > 0 ? '✗' : '✓'}</Text>
          <Text bold>{` ${padLabel(summaryLabel, nameWidth)}  `}</Text>
          {isSized ? <Text color="cyan">{barText(barWidth, fraction)}</Text> : null}
          {isSized ? <Text bold>{` ${String(Math.floor(fraction * 100)).padStart(3)}%`}</Text> : null}
          <Text dimColor>{`${isSized ? '  ' : ''}${[sizes, ...counts].join(' · ')} `}</Text>
          {hideButton}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        {top}
        {rows.map((row, i) => {
          const isSized = row.total !== null && row.bytes <= row.total * 1.05
          const total = row.total ?? 0
          const name = ` ${padLabel(row.label, nameWidth)}  `
          const hide = i === 0 && top === null ? hideButton : null

          if (row.status === 'failed') {
            return (
              <Box key={`row-${row.id}`}>
                <Text color="red">{'✗'}</Text>
                <Text>{name}</Text>
                <Text color="red">{`failed (exit ${row.exitCode ?? '?'})`}</Text>
                <Text dimColor>{` · ${formatBytes(row.bytes)} `}</Text>
                {hide}
              </Box>
            )
          }

          if (row.status === 'done') {
            return (
              <Box key={`row-${row.id}`}>
                <Text color="green">{'✓'}</Text>
                <Text>{name}</Text>
                {isSized ? <Text color="green">{`${barText(barWidth, 1)} 100%`}</Text> : null}
                <Text dimColor>{` ${formatBytes(isSized ? total : row.bytes)} `}</Text>
                {hide}
              </Box>
            )
          }

          const fraction = isSized ? Math.min(0.99, row.bytes / total) : 0
          const sizes = isSized ? `${formatBytes(row.bytes)} / ${formatBytes(total)}` : formatBytes(row.bytes)
          const eta = isSized && row.rate > 0 ? ` · ETA ${formatDuration((total - row.bytes) / row.rate)}` : ''

          return (
            <Box key={`row-${row.id}`}>
              <Text color="cyan">{'↓'}</Text>
              <Text>{name}</Text>
              {isSized ? <Text color="cyan">{barText(barWidth, fraction)}</Text> : null}
              {isSized ? <Text bold>{` ${String(Math.floor(fraction * 100)).padStart(3)}%`}</Text> : null}
              <Text dimColor>{`${isSized ? '  ' : ''}${sizes} · ${formatBytes(row.rate)}/s${eta} `}</Text>
              {hide}
            </Box>
          )
        })}
      </Box>
    )
  })

  on('command.run', { command: 'dlbar' }, async ($, e) => {
    const [word = '', arg = ''] = e.args.trim().toLowerCase().split(/\s+/)
    const cfg = await settings($)

    if (word === 'on' || word === 'off') {
      await $.store.set('on', word === 'on')
      return { text: `Download bar ${word}.` }
    }
    if (word === 'test') {
      if (S.isSimulating) return { text: 'A simulated download is already running.' }
      const count = Math.max(2, Math.min(50, Number.parseInt(arg, 10) || 2))
      simulate($, await $.clock.now(), count)
      return {
        text:
          count === 2
            ? 'Simulating two downloads (one with a known size, one without). Look above the prompt.'
            : `Simulating ${count} downloads. Look above the prompt.`,
      }
    }
    if (word === 'lookup') {
      if (arg !== 'on' && arg !== 'off') return { text: 'Usage: /dlbar lookup on|off' }
      await $.store.set('lookup', arg === 'on')
      return { text: `Size lookup ${arg}.` }
    }

    return {
      text: [
        `Download bar: ${cfg.isOn ? 'on' : 'off'} · size lookup ${cfg.isLookup ? 'on' : 'off'}`,
        'Shows one row per download started from Claude Code\'s shells: any program that holds an internet connection and writes what it receives, in WSL too.',
        'Percent and ETA appear when the download\'s URL reports its size (a HEAD request, sent only once the download is running).',
        `Past ${MAX_ROWS} at once, one summary row tops the ${DETAIL_ROWS} fastest.`,
        '/dlbar test [count] · /dlbar on|off · /dlbar lookup on|off',
      ].join('\n'),
    }
  })
}

files.hooks/lib.ts:
// Pure helpers: no `$`, so the tests reach them directly. The sampler
// (sampler/sampler.ps1) reports processes; `advance` turns reports into rows.

/** One process the sampler reports: a Claude Code shell descendant that held an internet connection. */
export type ProcReport = {
  pid: number
  /** Executable name, `curl.exe`. */
  n: string
  /** Bytes the process has written, for its whole life. */
  w: number
  /** Connected to a non-loopback address right now. */
  c: boolean
  /** Command line, on the first report only. */
  cmd?: string
  /** Working directory, on the first report only. */
  cwd?: string
  /** Exit code, on the last report only. */
  x?: number
}

/** A `wsl.exe` a Claude Code shell started: its download runs in the Linux VM, followed by sampler/wsl-sampler.sh. */
export type WslLaunch = {
  pid: number
  cmd: string
  /** Exit code, on the last report only. */
  x?: number
}

export type Report = { rx: number; p: ProcReport[]; wsl?: WslLaunch[] }

export function parseReport(line: string): Report | null {
  try {
    const value = JSON.parse(line) as Partial<Report>
    if (typeof value.rx !== 'number' || !Array.isArray(value.p)) return null
    return value as Report
  } catch {
    return null
  }
}

export type RowStatus = 'active' | 'done' | 'failed'

export type RowState = {
  pid: number
  exe: string
  cmd: string
  label: string
  urls: string[]
  /** The script an interpreter runs, resolved against its working directory. */
  script: string | null
  /** The file a resumed download (curl -C, wget -c) appends to, resolved the same way. */
  resumeFile: string | null
  /** Write count when this download began; progress is counted from here. */
  base: number
  /** Machine bytes received when it began, to check data really came in. */
  rxBase: number
  /** Write count when the sampler first saw it, for the network check. */
  seenWrites: number
  writes: number
  rate: number
  lastAt: number
  lastActiveAt: number
  firstSeen: number
  isVisible: boolean
  status: RowStatus
  exitCode: number | null
  endedAt: number
  total: number | null
}

// A row shows once a process has written this much...
export const MIN_VISIBLE_BYTES = 256 * 1024
// ...and at least this share of it arrived over the network meanwhile, so a
// job writing checkpoints beside an idle connection is not a "download".
export const MIN_RX_SHARE = 0.25
// A process that is still running but neither connected nor writing for this
// long has finished its download.
export const IDLE_MS = 3000
export const DONE_LINGER_MS = 1500
export const FAILED_LINGER_MS = 4000
const SMOOTHING = 0.5
const SHELLS = /^(bash|sh|zsh|pwsh|powershell)\.exe$/i

export type Advance = {
  rows: Map<number, RowState>
  /** Rows that became visible on this report: the time to look up a size. */
  appeared: RowState[]
}

export function advance(
  rows: Map<number, RowState>,
  report: Report,
  now: number,
  labelFor: (exe: string, cmd: string, firstSeen: number) => Description,
): Advance {
  const next = new Map(rows)
  const appeared: RowState[] = []

  for (const p of report.p) {
    let row = next.get(p.pid)
    if (row === undefined) {
      const cmd = p.cmd ?? ''
      const { label, urls, script } = labelFor(p.n, cmd, now)
      const resumed = resumedOutput(p.n, cmd)
      const resumeFile = resumed === null ? null : resolvePath(p.cwd ?? '', resumed)
      row = {
        pid: p.pid,
        exe: p.n,
        cmd,
        label,
        urls,
        script: script === undefined ? null : resolvePath(p.cwd ?? '', script),
        // Only a path made absolute is the file the download writes.
        resumeFile: resumeFile !== null && /^([a-z]:[\\/]|[\\/]{2})/i.test(resumeFile) ? resumeFile : null,
        // A shell runs other work before downloading, so count from now; any
        // other program's whole life is the download, so count from zero.
        base: SHELLS.test(p.n) ? p.w : 0,
        rxBase: report.rx,
        seenWrites: p.w,
        writes: p.w,
        rate: 0,
        lastAt: now,
        lastActiveAt: now,
        firstSeen: now,
        isVisible: false,
        status: 'active',
        exitCode: null,
        endedAt: 0,
        total: null,
      }
    } else {
      row = { ...row }
    }

    const delta = Math.max(0, p.w - row.writes)
    const seconds = (now - row.lastAt) / 1000
    if (seconds > 0) {
      const instant = delta / seconds
      row.rate = row.rate === 0 ? instant : SMOOTHING * instant + (1 - SMOOTHING) * row.rate
    }
    row.writes = p.w
    row.lastAt = now
    if (delta > 0 || p.c) row.lastActiveAt = now

    // A process that finished one download and starts another (a PowerShell
    // session fetching twice) begins a fresh row.
    if (row.status !== 'active' && p.x === undefined && p.c && delta > 0) {
      row = { ...row, base: p.w - delta, rxBase: report.rx, seenWrites: p.w - delta, firstSeen: now, isVisible: false, status: 'active', exitCode: null, endedAt: 0, rate: 0 }
    }

    const bytes = row.writes - row.base
    if (!row.isVisible && row.status === 'active' && bytes >= MIN_VISIBLE_BYTES && report.rx - row.rxBase >= MIN_RX_SHARE * (row.writes - row.seenWrites)) {
      row.isVisible = true
      appeared.push(row)
    }

    if (p.x !== undefined) {
      if (row.status === 'active') {
        row.status = p.x === 0 ? 'done' : 'failed'
        row.exitCode = p.x
        row.endedAt = now
      }
    } else if (row.status === 'active' && !p.c && now - row.lastActiveAt >= IDLE_MS) {
      row.status = 'done'
      row.endedAt = now
    }

    next.set(p.pid, row)
  }

  // The sampler always reports an exit, so a row it stops naming has ended.
  const named = new Set(report.p.map(p => p.pid))
  for (const [pid, row] of next) {
    if (!named.has(pid) && row.status === 'active') next.set(pid, { ...row, status: 'done', endedAt: now })
  }

  for (const [pid, row] of next) {
    if (row.status === 'active') continue
    const linger = row.status === 'failed' ? FAILED_LINGER_MS : DONE_LINGER_MS
    if (!row.isVisible || now - row.endedAt >= linger) {
      // Only drop a row the sampler has let go of; a live one may download again.
      if (!named.has(pid) || row.exitCode !== null) next.delete(pid)
      else if (row.isVisible) next.set(pid, { ...row, isVisible: false })
    }
  }

  return { rows: next, appeared }
}

// A sampler that ends is started again, up to this many times in a row...
export const MAX_SAMPLER_RESTARTS = 3
// ...unless it ran this long before it ended: that was not a crash loop, so its end starts the count over.
export const HEALTHY_MS = 60_000

/** The restarts used once a sampler that ran `ranMs` has ended, or null when none is left. */
export function restartsAfter(used: number, ranMs: number): number | null {
  const counted = ranMs >= HEALTHY_MS ? 0 : used
  return counted < MAX_SAMPLER_RESTARTS ? counted + 1 : null
}

export function formatBytes(n: number): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let value = Math.max(0, n)
  let i = 0
  while (value >= 1024 && i < units.length - 1) {
    value /= 1024
    i++
  }
  return `${value >= 100 || i === 0 ? Math.round(value) : value.toFixed(1)} ${units[i]}`
}

export function formatDuration(seconds: number): string {
  const s = Math.max(0, Math.round(seconds))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, '0')}s`
  return `${Math.floor(s / 3600)}h ${String(Math.floor((s % 3600) / 60)).padStart(2, '0')}m`
}

const URL_PATTERN = /https?:\/\/[^\s'"`<>)|;&\\]+/gi

export function extractUrls(text: string, limit = 5): string[] {
  const found = text.match(URL_PATTERN) ?? []
  return [...new Set(found.map(u => u.replace(/[.,]+$/, '')))].slice(0, limit)
}

export function fileLabel(url: string): string {
  const path = url.replace(/^https?:\/\//i, '').split(/[?#]/)[0] ?? ''
  const last = path.split('/').filter(Boolean).pop() ?? path
  try {
    return decodeURIComponent(last)
  } catch {
    return last
  }
}

// The file a command says it writes: curl -o, wget -O, aria2c -o/--out,
// -OutFile. A bare `curl -O` has no name of its own, so the URL gives it.
const OUTPUT_FLAG = /(?:^|\s)(?:-o|-O|--output|--output-document|--out|-OutFile)(?:\s+|=)("[^"]+"|'[^']+'|[^\s;&|]+)/i

export function outputName(command: string): string | null {
  const raw = OUTPUT_FLAG.exec(command)?.[1]
  if (raw === undefined) return null
  const value = raw.replace(/^["']|["']$/g, '')
  if (/^https?:/i.test(value) || /^(-|\/dev\/null|nul)$/i.test(value)) return null
  return value.split(/[\\/]/).filter(Boolean).pop() ?? null
}

/**
 * The output file a download resumes into (curl -C, wget -c, aria2c -c), as
 * its command names it, or null for one that starts the file over. Bytes
 * already in that file are progress its own write count never sees.
 */
export function resumedOutput(exe: string, command: string): string | null {
  const program = baseName(exe).replace(/\.exe$/i, '').toLowerCase()
  const resumes =
    program === 'curl' ? /\s(-C|--continue-at)(\s|=)/.test(command) : /^(wget|aria2c)$/.test(program) && /\s(-c|--continue)(\s|=|$)/.test(command)
  if (!resumes) return null
  const raw = OUTPUT_FLAG.exec(command)?.[1]
  if (raw === undefined) return null
  const value = raw.replace(/^["']|["']$/g, '')
  return /^https?:/i.test(value) || /^(-|\/dev\/null|nul|~.*)$/i.test(value) ? null : value
}

/** Splits a Windows command line into arguments (quotes respected, not unescaped further). */
export function splitArgs(cmd: string): string[] {
  return (cmd.match(/"[^"]*"|\S+/g) ?? []).map(a => a.replace(/^"|"$/g, ''))
}

function baseName(path: string): string {
  return path.split(/[\\/]/).filter(Boolean).pop() ?? path
}

const INTERPRETERS = /^(python\d*(\.\d+)?|pythonw|py|node|deno|bun|ruby|perl|php|uv)(\.exe)?$/i
const PACKAGE_TOOLS = /^(pip\d*|uv|npm|pnpm|yarn|conda|cargo|winget|choco|git|huggingface-cli|hf)$/i

export type Description = {
  label: string
  /** URLs on the command line. */
  urls: string[]
  /** A source file the interpreter runs (as written, maybe relative), whose URLs may say the size. */
  script?: string
}

const SOURCE_FILE = /\.(py|pyw|js|mjs|cjs|ts|rb|pl|php)$/i

/**
 * What to call a download from its process's own command line: the output
 * file it names, else the file in its URL, else the script an interpreter
 * runs, else the program.
 */
export function describe(exe: string, cmd: string): Description {
  const urls = extractUrls(cmd)
  const output = outputName(cmd)
  const program = exe.replace(/\.exe$/i, '')
  const args = splitArgs(cmd).slice(1)

  const isInterpreter = INTERPRETERS.test(exe)
  // `-c <code>` runs inline code: no script to name it after.
  const scriptArg = isInterpreter && !args.includes('-c') && !args.includes('-m') ? args.find(a => !a.startsWith('-')) : undefined
  const script = scriptArg !== undefined && SOURCE_FILE.test(scriptArg) ? { script: scriptArg } : {}

  if (output !== null) return { label: withMore(output, urls.length), urls, ...script }

  if (isInterpreter) {
    const moduleIndex = args.indexOf('-m')
    if (moduleIndex !== -1 && args[moduleIndex + 1] !== undefined) {
      return { label: tool(args[moduleIndex + 1] as string, args.slice(moduleIndex + 2)), urls }
    }
    if (scriptArg !== undefined) {
      const name = baseName(scriptArg).replace(/\.exe$/i, '').replace(/^(npm|npx|pnpm|yarn)(-cli)?\.c?js$/i, '$1')
      if (PACKAGE_TOOLS.test(name)) return { label: tool(name, args.slice(args.indexOf(scriptArg) + 1)), urls }
      return { label: name, urls, ...script }
    }
  }

  if (/^git-remote-https?$/i.test(program)) return { label: 'git', urls }
  if (urls.length > 0) return { label: withMore(fileLabel(urls[0] as string), urls.length), urls }
  if (PACKAGE_TOOLS.test(program)) return { label: tool(program, args), urls }
  return { label: program, urls }
}

/** A path as a program got it, made absolute against that program's working directory. */
export function resolvePath(cwd: string, path: string): string {
  if (/^[a-z]:[\\/]/i.test(path) || /^[\\/]{2}/.test(path)) return path
  // A Linux program's absolute path, inside the distro its cwd is in.
  const distro = /^\\\\wsl(?:\.localhost|\$)\\[^\\]+/i.exec(cwd)
  if (distro !== null && path.startsWith('/')) return `${distro[0]}${path.replace(/\//g, '\\')}`
  // Git Bash hands native programs /c/... paths converted, but be safe.
  const drive = /^\/([a-z])\/(.*)$/i.exec(path)
  if (drive !== null) return `${(drive[1] as string).toUpperCase()}:/${drive[2]}`
  if (cwd === '') return path
  return `${cwd.replace(/[\\/]+$/, '')}\\${path.replace(/^\.[\\/]/, '')}`
}

/**
 * Which looked-up URLs are files to download, by their HEAD answers: a size
 * of at least `MIN_VISIBLE_BYTES` and not a page or an API reply. A script
 * names pages and APIs too; their sizes are no part of the download.
 */
export function downloadSizes(heads: ({ size: number; type: string } | null)[]): number | null {
  const files = heads.filter(
    (h): h is { size: number; type: string } =>
      h !== null && h.size >= MIN_VISIBLE_BYTES && !/^(text\/|application\/(json|xml|xhtml))/i.test(h.type),
  )
  return files.length === 0 ? null : files.reduce((sum, h) => sum + h.size, 0)
}

function tool(name: string, rest: string[]): string {
  const words = rest.filter(a => !a.startsWith('-')).slice(0, 2)
  return [name, ...words].join(' ')
}

function withMore(label: string, count: number): string {
  return count > 1 ? `${label} +${count - 1}` : label
}

/** The command Claude gave a shell tool, when that shell process is itself the downloader. */
export function isLauncherWrapper(cmd: string): boolean {
  return /__claudeCodeScript|shell-snapshots[\\/]snapshot-/i.test(cmd)
}

// wsl.exe options that take a value.
const WSL_VALUE_OPTIONS = /^(-d|--distribution|--distribution-id|-u|--user|--cd|--shell-type)$/i
const LEADING_WORD = /^\s*("[^"]*"|\S+)/

/**
 * What a `wsl.exe` command line runs: the distro it names ('' for the
 * default) and the command after its options, or null when it runs none
 * (an interactive shell, `--list`, `--shutdown`).
 */
export function wslCommand(cmd: string): { distro: string; command: string } | null {
  let rest = cmd.replace(LEADING_WORD, '')
  let distro = ''
  for (;;) {
    const word = LEADING_WORD.exec(rest)
    if (word === null) return null
    const name = (word[1] as string).replace(/^"|"$/g, '')
    const after = rest.slice(word[0].length)
    if (name === '--' || name === '-e' || name === '--exec') {
      const command = after.trim()
      return command === '' ? null : { distro, command }
    }
    if (WSL_VALUE_OPTIONS.test(name)) {
      const value = LEADING_WORD.exec(after)
      if (value === null) return null
      if (/^(-d|--distribution)$/i.test(name)) distro = (value[1] as string).replace(/^"|"$/g, '')
      rest = after.slice(value[0].length)
    } else if (name === '~' || name === '--system') {
      rest = after
    } else if (name.startsWith('-')) {
      return null
    } else {
      return { distro, command: rest.trim() }
    }
  }
}

function words(cmd: string): string[] {
  return cmd.replace(/["'\\]/g, '').split(/\s+/).filter(Boolean)
}

/**
 * Whether a Linux process that WSL started (its argv joined) is the one a
 * wsl.exe `command` ran. WSL hands the command to a shell first, so quotes
 * are gone and `$HOME` or `$?` arrive expanded: most words must agree, not all.
 */
export function isWslCommand(linux: string, command: string): boolean {
  const ours = words(command).filter(w => !/[$`]/.test(w))
  const theirs = words(linux)
  if (ours.length === 0 || theirs.length === 0) return false
  const pool = new Map<string, number>()
  for (const w of theirs) pool.set(w, (pool.get(w) ?? 0) + 1)
  let shared = 0
  for (const w of ours) {
    const left = pool.get(w) ?? 0
    if (left > 0) {
      shared++
      pool.set(w, left - 1)
    }
  }
  return shared >= 0.75 * ours.length && shared >= 0.5 * theirs.length
}

/** One Linux process the WSL sampler reports: it held an internet connection. */
export type WslProc = {
  pid: number
  /** The process WSL started that this one descends from, 0 when none. */
  root: number
  /** Bytes it has written (/proc/<pid>/io wchar). */
  w: number
  c: boolean
  n: string
  cwd: string
  cmd: string
}

export type WslTick = { procs: WslProc[]; roots: Map<number, string> }

/** One block of wsl-sampler.sh's lines, between its T and E. */
export function parseWslTick(lines: string[]): WslTick {
  const procs: WslProc[] = []
  const roots = new Map<number, string>()
  for (const line of lines) {
    const f = line.split('\t')
    if (f[0] === 'P' && f.length >= 8) {
      const [pid, root, w] = [Number(f[1]), Number(f[2]), Number(f[3])]
      if (Number.isInteger(pid) && Number.isInteger(root) && Number.isFinite(w)) {
        procs.push({ pid, root, w, c: f[4] === '1', n: f[5] as string, cwd: f[6] as string, cmd: f.slice(7).join(' ') })
      }
    } else if (f[0] === 'R' && f.length >= 3) {
      roots.set(Number(f[1]), f.slice(2).join(' '))
    }
  }
  return { procs, roots }
}

/** A Linux process's row id: past every Windows process id, apart for each distro. */
export function wslId(slot: number, pid: number): number {
  return 2 ** 32 + slot * 2 ** 23 + pid
}

/** A Linux path as Windows reaches it. */
export function wslPath(distro: string, path: string): string {
  return path.startsWith('/') ? `\\\\wsl.localhost\\${distro}${path.replace(/\//g, '\\')}` : path
}

/** A WSL tick as a sampler report, holding only the processes under roots `isOurs` accepts. */
export function wslReport(tick: WslTick, slot: number, distro: string, rx: number, isOurs: (root: number, cmd: string) => boolean): Report {
  const p = tick.procs
    .filter(proc => proc.root > 0 && isOurs(proc.root, tick.roots.get(proc.root) ?? ''))
    .map(proc => ({ pid: wslId(slot, proc.pid), n: proc.n, w: proc.w, c: proc.c, cmd: proc.cmd, cwd: wslPath(distro, proc.cwd) }))
  return { rx, p }
}

export function barText(width: number, fraction: number): string {
  const filled = Math.max(0, Math.min(width, Math.round(fraction * width)))
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

export function padLabel(label: string, width: number): string {
  if (label.length <= width) return label.padEnd(width)
  return `${label.slice(0, Math.max(1, width - 1))}…`
}

/** A row as the panel draws it. */
export type PanelRow = {
  id: number
  label: string
  bytes: number
  total: number | null
  rate: number
  status: RowStatus
  exitCode: number | null
}

/** Downloads that finished and left the panel during the current batch. */
export type Finished = { done: number; failed: number; bytes: number; total: number; hasUnknownTotal: boolean }

export const noneFinished: Finished = { done: 0, failed: 0, bytes: 0, total: 0, hasUnknownTotal: false }

export type PanelSummary = {
  count: number
  active: number
  done: number
  failed: number
  bytes: number
  total: number | null
  rate: number
}

export const MAX_ROWS = 4
export const DETAIL_ROWS = 3
// A shown row keeps its place while this fast relative to the DETAIL_ROWS-th fastest.
const KEEP_RATE = 0.8

export type Layout = { rows: PanelRow[]; summary: PanelSummary | null; pinned: number[] }

/**
 * Up to MAX_ROWS downloads show whole. Past that the panel turns into one
 * summary row over the DETAIL_ROWS fastest active downloads. A shown row
 * keeps its place until it falls clearly behind (below KEEP_RATE of the
 * DETAIL_ROWS-th fastest), so rows do not swap every half second; `pinned`
 * carries that choice between calls.
 */
export function layout(rows: PanelRow[], pinned: number[], finished: Finished, isSummaryMode: boolean): Layout {
  if (!isSummaryMode && rows.length <= MAX_ROWS) return { rows, summary: null, pinned: [] }

  const active = rows.filter(r => r.status === 'active')
  const byRate = [...active].sort((a, b) => b.rate - a.rate)
  const keepAbove = (byRate[DETAIL_ROWS - 1]?.rate ?? 0) * KEEP_RATE
  const chosen = pinned.filter(id => active.some(r => r.id === id && r.rate >= keepAbove))
  for (const r of byRate) {
    if (chosen.length >= DETAIL_ROWS) break
    if (!chosen.includes(r.id)) chosen.push(r.id)
  }
  // With few left downloading, show the latest failures, then completions.
  for (const status of ['failed', 'done'] as const) {
    for (const r of [...rows].reverse()) {
      if (chosen.length >= DETAIL_ROWS) break
      if (r.status === status && !chosen.includes(r.id)) chosen.push(r.id)
    }
  }

  const hasUnknownTotal = finished.hasUnknownTotal || rows.some(r => r.total === null)
  const summary: PanelSummary = {
    count: rows.length + finished.done + finished.failed,
    active: active.length,
    done: rows.filter(r => r.status === 'done').length + finished.done,
    failed: rows.filter(r => r.status === 'failed').length + finished.failed,
    bytes: rows.reduce((sum, r) => sum + r.bytes, 0) + finished.bytes,
    total: hasUnknownTotal ? null : rows.reduce((sum, r) => sum + (r.total ?? 0), 0) + finished.total,
    rate: active.reduce((sum, r) => sum + r.rate, 0),
  }

  return { rows: rows.filter(r => chosen.includes(r.id)), summary, pinned: chosen.filter(id => active.some(r => r.id === id)) }
}

