export type DownloadRow = {
  /** The downloading process (or a negative id for /dlbar test rows). */
  id: number
  /** The file, script or program, for the row's name column. */
  label: string
  /** Bytes written by the process since the download began. */
  bytes: number
  /** Expected size, when the download's URLs reported one. */
  total: number | null
  /** Smoothed bytes per second. */
  rate: number
  status: 'active' | 'done' | 'failed'
  exitCode: number | null
}

/** The row over the rest when more downloads run than fit. */
export type DownloadSummary = {
  /** Downloads in this batch, finished ones included. */
  count: number
  active: number
  done: number
  failed: number
  bytes: number
  /** Combined size, when every download's size is known. */
  total: number | null
  rate: number
}

declare module 'claude-code' {
  interface PluginState {
    'download-bar': { rows: DownloadRow[]; summary: DownloadSummary | null; isHidden: boolean }
  }
}
